WITH latest_match AS (SELECT s.*, latest.sale_date FROM stores s LEFT JOIN LATERAL (SELECT c.sale_date FROM store_sales c WHERE c.store_id = s.id ORDER BY c.sale_date DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT city, SUM(CASE WHEN region = 'East' THEN sqft ELSE 0 END) AS east_sqft, SORT_ARRAY(COLLECT_SET(city)) AS city_list, ROUND(SUM(sqft) / NULLIF(COUNT(CASE WHEN region = 'Central' THEN 1 END), 0), 2) AS sqft_per_central FROM latest_match GROUP BY city
